param([ValidateSet('git','none','plastic')][string]$Kind='none',[int]$Round=2,[int]$Code=102,[int]$Value=102,[string]$TraceSuffix='')
. "$PSScriptRoot/scalable-unity-common.ps1" -Kind $Kind
if($TraceSuffix -and $TraceSuffix -notmatch '^[a-z0-9-]+$'){throw 'Use a distinct safe observation suffix'}
$scalObservedEval=${function:Eval}
function Eval([string]$Name,[string]$Project,[string]$Code){ & $scalObservedEval ($Name+$TraceSuffix) $Project $Code }
Eval ('round-'+$Round+'-precompile-preserve-new-dirty') $source 'for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new System.Exception("Preserve new dirty scene before compilation");foreach(var obj in UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.Object>()){var p=UnityEditor.AssetDatabase.GetAssetPath(obj);if(p.StartsWith("Assets/")&&UnityEditor.EditorUtility.IsDirty(obj))throw new System.Exception("Preserve new dirty asset before compilation");}return new {safe=true};'|Out-Null
Compile ('round-'+$Round+'-original-compile') $source $Code | Out-Null
$proof=Eval ('round-'+$Round+'-original-loaded-confirmed') $source 'for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new System.Exception("Preserve new dirty scene");foreach(var obj in UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.Object>()){var p=UnityEditor.AssetDatabase.GetAssetPath(obj);if(p.StartsWith("Assets/")&&UnityEditor.EditorUtility.IsDirty(obj))throw new System.Exception("Preserve new dirty asset");}UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/RI.unity");var t=System.Type.GetType("RiData, Assembly-CSharp");var a=UnityEditor.AssetDatabase.LoadAssetAtPath("Assets/RI.asset",t);return new {pid=System.Diagnostics.Process.GetCurrentProcess().Id,startTicks=System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks.ToString(),code=(int)System.Type.GetType("RiValue, Assembly-CSharp").GetProperty("Current").GetValue(null),mvid=t.Assembly.ManifestModule.ModuleVersionId.ToString(),scene=UnityEngine.GameObject.Find("RiCube").transform.position.x,asset=(int)t.GetField("Value").GetValue(a),unrelated=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/OriginalOnly.mat").color.r,unrelatedGreen=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/OriginalOnly.mat").color.g,unrelatedBlue=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/OriginalOnly.mat").color.b};'
if($proof.code -ne $Code -or $proof.scene -ne $Value -or $proof.asset -ne $Value -or $proof.unrelated -ne 1 -or $proof.unrelatedGreen -ne 0 -or $proof.unrelatedBlue -ne 0){throw 'Loaded original values differ'}
$proof|ConvertTo-Json
$b=(Get-Content (Join-Path $evidence 'ensure-b.json') -Raw|ConvertFrom-Json).data.workspace
$peer=Eval ('round-'+$Round+'-peer-continues') $b.path ('new UnityEngine.GameObject("PeerAfterRound'+$Round+'");UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());var t=System.Type.GetType("RiData, Assembly-CSharp");var a=UnityEditor.AssetDatabase.LoadAssetAtPath("Assets/RI.asset",t);return new {pid=System.Diagnostics.Process.GetCurrentProcess().Id,startTicks=System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks.ToString(),code=(int)System.Type.GetType("RiValue, Assembly-CSharp").GetProperty("Current").GetValue(null),scene=UnityEngine.GameObject.Find("RiCube").transform.position.x,asset=(int)t.GetField("Value").GetValue(a),dirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty};');$peer|ConvertTo-Json
if($peer.code -ne 1 -or $peer.scene -ne 201 -or $peer.asset -ne 201 -or -not $peer.dirty){throw 'The peer source, unsaved scene or asset changed during another task publication'}
